1	import { useEffect, useRef, useState, type FormEvent } from "react";
2	import { useMutation } from "convex/react";
3	import { ConvexError } from "convex/values";
4	import { api } from "../convex/_generated/api";
5	import { isValidEmail } from "./lib";
6	
7	// The public /#/join waitlist. One page that becomes two: a wide viewport gets
8	// the "constellation" layout (copy settled in the lower third), a narrow one
9	// gets the "drift" layout (headline up top, capture at the bottom). Both ride
10	// the same drifting star field. The 620px breakpoint drives layout and copy
11	// together so they never disagree.
12	type Mode = "desktop" | "phone";
13	// "already" is a first-class outcome, not an error: the person is on the list,
14	// they just submitted a second time. The server dedups by email and returns it
15	// so the UI can say so honestly instead of faking a fresh "joined" (which would
16	// promise a confirmation email that never comes for a repeat).
17	type Status = "idle" | "submitting" | "joined" | "already";
18	
19	const BREAKPOINT = 620;
20	
21	function initialMode(): Mode {
22	  return typeof window !== "undefined" && window.innerWidth >= BREAKPOINT
23	    ? "desktop"
24	    : "phone";
25	}
26	
27	// Copy shifts with the layout; each side keeps the wording it was designed with.
28	const COPY: Record<Mode, {
29	  headline: string;
30	  sub: string;
31	  cta: string;
32	  fine: string;
33	}> = {
34	  desktop: {
35	    headline: "Your people are a constellation.",
36	    sub: "Every person you meet becomes a point of light - and Haven keeps them from drifting away.",
37	    cta: "Join",
38	    fine: "Private beta",
39	  },
40	  phone: {
41	    headline: "The people you meet, never lost again.",
42	    sub: "A quiet memory layer over the people of your life. Get in early.",
43	    cta: "Request access",
44	    fine: "No spam. Invites go out in waves.",
45	  },
46	};
47	
48	function CheckIcon() {
49	  return (
50	    <svg viewBox="0 0 24 24" fill="none" stroke="#0a84ff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
51	      <path d="M20 6 9 17l-5-5" />
52	    </svg>
53	  );
54	}
55	
56	export function Waitlist() {
57	  const rootRef = useRef<HTMLDivElement | null>(null);
58	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
59	  const [mode, setMode] = useState<Mode>(initialMode);
60	  const [name, setName] = useState("");
61	  const [email, setEmail] = useState("");
62	  // The email row stays folded until the person engages the name field, so the
63	  // page opens as one calm line. Once revealed it stays revealed.
64	  const [revealed, setRevealed] = useState(false);
65	  const [status, setStatus] = useState<Status>("idle");
66	  const [error, setError] = useState<string | null>(null);
67	  const join = useMutation(api.waitlist.joinWaitlist);
68	
69	  // Layout follows the page width, flipping at the same breakpoint the copy
70	  // uses so the two stay in step.
71	  useEffect(() => {
72	    const root = rootRef.current;
73	    if (root === null) return;
74	    const observer = new ResizeObserver(([entry]) => {
75	      setMode(entry.contentRect.width >= BREAKPOINT ? "desktop" : "phone");
76	    });
77	    observer.observe(root);
78	    return () => observer.disconnect();
79	  }, []);
80	
81	  // The drifting star field. Lives for the component's lifetime and tears
82	  // down its animation frame on unmount; a still frame under reduced motion.
83	  useEffect(() => {
84	    const canvas = canvasRef.current;
85	    if (canvas === null) return;
86	    return startDrift(canvas);
87	  }, []);
88	
89	  async function onSubmit(event: FormEvent) {
90	    event.preventDefault();
91	    setError(null);
92	    // Checked in field order (name above email) so the first error shown is
93	    // the first thing the person needs to fix.
94	    if (name.trim() === "") {
95	      setError("Enter your name.");
96	      return;
97	    }
98	    if (!isValidEmail(email)) {
99	      setError("Enter a valid email address.");
100	      return;
101	    }
102	    setStatus("submitting");
103	    try {
104	      // Honor the server's dedup verdict: a repeat email comes back "already"
105	      // (no new row, no email), so show that instead of a false fresh join.
106	      const result = await join({ name: name.trim(), email, source: mode });
107	      setStatus(result.status === "already" ? "already" : "joined");
108	    } catch (err) {
109	      setStatus("idle");
110	      // ConvexError carries our own server message; anything else is a network
111	      // or unexpected failure the person can just retry.
112	      setError(
113	        err instanceof ConvexError && typeof err.data === "string"
114	          ? err.data
115	          : "Something went wrong. Please try again.",
116	      );
117	    }
118	  }
119	
120	  const copy = COPY[mode];
121	
122	  return (
123	    <div ref={rootRef} className="waitlist" data-mode={mode}>
124	      <canvas ref={canvasRef} className="wl-sky" aria-hidden="true" />
125	      <div className="wl-content">
126	        {status === "joined" || status === "already" ? (
127	          <div className="wl-joined" role="status">
128	            <div className="wl-check" aria-hidden="true">
129	              <CheckIcon />
130	            </div>
131	            <p className="wl-checkline">
132	              {status === "already"
133	                ? "You're already on the list."
134	                : "You are on the list."}
135	            </p>
136	            <p className="wl-sub wl-joined-sub">
137	              {status === "already"
138	                ? "This email is already registered - no need to sign up again. We'll be in touch."
139	                : "Thank you for joining us, to be in the true social that brings you to other people in your life"}
140	            </p>
141	          </div>
142	        ) : (
143	          <>
144	            <div className="wl-top">
145	              <span className="wl-eyebrow">Haven - private beta</span>
146	              <h1 className="wl-headline">{copy.headline}</h1>
147	            </div>
148	            <div className="wl-bottom">
149	              <p className="wl-sub">{copy.sub}</p>
150	              <form
151	                className={revealed ? "wl-form is-revealed" : "wl-form"}
152	                onSubmit={onSubmit}
153	                noValidate
154	              >
155	                <div className="wl-name-row">
156	                  <input
157	                    className="wl-field"
158	                    type="text"
159	                    autoComplete="name"
160	                    placeholder="Your name"
161	                    aria-label="Your name"
162	                    value={name}
163	                    onFocus={() => setRevealed(true)}
164	                    onChange={(event) => {
165	                      setName(event.target.value);
166	                      setRevealed(true);
167	                      if (error !== null) setError(null);
168	                    }}
169	                  />
170	                  {/* Join rides alongside the name until the email drops in,
171	                      then hands off to the email row's button. */}
172	                  <button
173	                    className="wl-go wl-go-name"
174	                    type="submit"
175	                    disabled={status === "submitting"}
176	                    inert={revealed}
177	                  >
178	                    {status === "submitting" ? "Joining" : copy.cta}
179	                  </button>
180	                </div>
181	                <div className="wl-email-wrap" inert={!revealed}>
182	                  <div className="wl-email-row">
183	                    <input
184	                      className="wl-field"
185	                      type="email"
186	                      inputMode="email"
187	                      autoComplete="email"
188	                      placeholder="Your email"
189	                      aria-label="Email address"
190	                      value={email}
191	                      onChange={(event) => {
192	                        setEmail(event.target.value);
193	                        if (error !== null) setError(null);
194	                      }}
195	                    />
196	                    <button className="wl-go" type="submit" disabled={status === "submitting"}>
197	                      {status === "submitting" ? "Joining" : copy.cta}
198	                    </button>
199	                  </div>
200	                </div>
201	              </form>
202	              {error !== null ? (
203	                <p className="wl-error" role="alert">{error}</p>
204	              ) : (
205	                <p className="wl-fine">{copy.fine}</p>
206	              )}
207	            </div>
208	          </>
209	        )}
210	      </div>
211	    </div>
212	  );
213	}
