215	type Star = {
216	  x: number;
217	  y: number;
218	  size: number;
219	  base: number;
220	  sp: number;
221	  tw: number;
222	  hot: boolean;
223	};
224	
225	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
226	// stars move faster. Returns its own teardown. Ported from the approved
227	// prototype so the shipped page matches it exactly.
228	function startDrift(canvas: HTMLCanvasElement): () => void {
229	  const ctx = canvas.getContext("2d");
230	  if (ctx === null) return () => {};
231	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
232	  let w = 0;
233	  let h = 0;
234	  let raf = 0;
235	  let stars: Star[] = [];
236	
237	  function size() {
238	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
239	    w = canvas.clientWidth;
240	    h = canvas.clientHeight;
241	    canvas.width = w * dpr;
242	    canvas.height = h * dpr;
243	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
244	  }
245	
246	  function build() {
247	    size();
248	    const count = Math.min(300, Math.floor((w * h) / 3600));
249	    stars = [];
250	    for (let i = 0; i < count; i++) {
251	      const depth = Math.random();
252	      stars.push({
253	        x: Math.random() * w,
254	        y: Math.random() * h,
255	        size: 0.5 + depth * 1.6,
256	        base: 0.1 + depth * 0.45,
257	        sp: 0.05 + depth * 0.22,
258	        tw: Math.random() * 6.28,
259	        hot: Math.random() < 0.04,
260	      });
261	    }
262	  }
263	
264	  function frame(t: number) {
265	    const time = t / 1000;
266	    ctx!.clearRect(0, 0, w, h);
267	    for (const s of stars) {
268	      if (!reduce) {
269	        s.x += s.sp;
270	        if (s.x > w + 2) s.x = -2;
271	      }
272	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
273	      ctx!.beginPath();
274	      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
275	      if (s.hot) {
276	        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
277	        ctx!.shadowColor = "rgba(10,132,255,.8)";
